public class IsomorphicGraphMapping<V, E> {

    private Map<String, VertexMapping> mappings = new HashMap<>();

    public void dedicate(VertexMapping mapping) {
        String vertexID = mapping.toVertexID(mapping.toVertexID(mapping.getVertex()));
        if (mappings.containsKey(vertexID)) {
            VertexMapping previousMapping = mappings.get(vertexID);
            previousMapping.removeVertexID(vertexID);
            mappings.remove(vertexID);
        }
        mappings.put(vertexID, mapping);
    }

    public boolean containsVertex(Object vertex) {
        return mappings.containsValue(vertex);
    }

    public Graph getAssociatedGraph() {
        return mappings.entrySet().stream()
                .map(e -> e.getValue().getVertex())
                .distinct()
                .collect(Collectors.toList());
    }

    public static <V, E> IsomorphicGraphMapping<V, E> identity(Graph<V, E> graph) {
        IsomorphicGraphMapping<V, E> mapping = new IsomorphicGraphMapping<>();
        for (V vertex : graph.getVertices()) {
            mapping.dedicate(new VertexMapping(vertex, vertex));
        }
        return mapping;
    }
}

