public class Graph<V, E> {

    private Set<V> vertices;
    private Set<E> edges;

    public Graph() {
        this.vertices = new LinkedHashSet<>();
        this.edges = new LinkedHashSet<>();
    }

    public void addVertex(V v) {
        if (v == null) {
            throw new IllegalArgumentException("Vertex cannot be null");
        } else if (!vertices.contains(v)) {
            vertices.add(v);
        }
    }

    public void removeVertex(V v) {
        if (v == null) {
            return;
        }
        vertices.remove(v);
    }

    public void addEdge(V v1, V v2) {
        if (v1 == null || v2 == null) {
            throw new IllegalArgumentException("Vertex cannot be null");
        } else if (v1 == v2) {
            return;
        } else if (!vertices.contains(v1) || !vertices.contains(v2)) {
            throw new IllegalArgumentException("Both vertices must be in the graph");
        } else if (!edges.contains(new Edge<>(v1, v2))) {
            edges.add(new Edge<>(v1, v2));
        }
    }

    public void removeEdge(V v1, V v2) {
        if (v1 == null || v2 == null) {
            return;
        }
        edges.remove(new Edge<>(v1, v2));
    }

    public Set<V> getVertices() {
        return vertices;
    }

    public Set<E> getEdges() {
        return edges;
    }
}

