protected List<TimeRange> buildTimeRanges(long start, long end) {
    // Calculate the number of time ranges to generate
    int numRanges = (int) Math.ceil((end - start) / FETCH_DATA_DURATION);

    // Create a new list to store the time ranges
    List<TimeRange> timeRanges = new ArrayList<>(numRanges);

    // Iterate over the desired number of time ranges
    for (int i = 0; i < numRanges; i++) {
        // Calculate the start and end time for the current range
        long rangeStart = start + (i * FETCH_DATA_DURATION);
        long rangeEnd = Math.min(end, rangeStart + FETCH_DATA_DURATION);

        // Add the current range to the list of time ranges
        timeRanges.add(new TimeRange(rangeStart, rangeEnd));
    }

    // Return the list of time ranges
    return timeRanges;
}

private List<TimeRange> buildTimeRanges(long start, long end, long FETCH_DATA_DURATION) {

List<TimeRange> timeRanges = new ArrayList<>();

if (start < FETCH_DATA_DURATION) {
start = 0;
}

while (end > FETCH_DATA_DURATION) {
TimeRange range = new TimeRange(start, FETCH_DATA_DURATION);
timeRanges.add(range);
start += FETCH_DATA_DURATION;
end = end - FETCH_DATA_DURATION;
}

if (end > 0) {
TimeRange range = new TimeRange(start, end);
timeRanges.add(range);
}

return timeRanges;
}

