public LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    // Write the length of the string to the LinkedBuffer
    lb.writeVarint(str.length());

    // Iterate over the characters of the string and write their utf8-encoded bytes to the LinkedBuffer
    for (int i = 0; i < str.length(); i++) {
        char ch = str.charAt(i);
        if (ch >= 0 && ch <= 0x7F) {
            lb.writeByte((byte) ch);
        } else if (ch >= 0x0080 && ch <= 0x07FF) {
            lb.writeByte((byte) (0xC0 | (ch >> 6)));
            lb.writeByte((byte) (0x80 | (ch & 0x3F)));
        } else {
            lb.writeByte((byte) (0xE0 | (ch >> 12)));
            lb.writeByte((byte) (0x80 | ((ch >> 6) & 0x3F)));
            lb.writeByte((byte) (0x80 | (ch & 0x3F)));
        }
    }

    return lb;
}

