public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();

    if (u == null || !u.getScheme().equals("http") || !u.getScheme().equals("https")) {
      return pathSegments;
    }

    String path = u.getRawPath();
    if (path == null || path.isEmpty()) {
      return pathSegments;
    }

    // Check if the path is an absolute path
    if (path.charAt(0) == '/') {
      // Ignore the leading '/' and consider it as a path separator
      path = path.substring(1);
    }

    // Split the path into segments using '/' as a separator
    String[] segments = path.split("/");
    for (String segment : segments) {
      if (decode) {
        // Decode the segment if the decode parameter is true
        segment = URLDecoder.decode(segment, StandardCharsets.UTF_8);
      }
      pathSegments.add(new PathSegmentImpl(segment));
    }

    return pathSegments;
  }

