private Object convertToType(Class<?> type, Object value) throws Exception {

        // Check if the value is null
        if (value == null) {
            return null;
        }

        // Check if the type is java.lang.Character
        if (type == Character.class || type == Character.TYPE) {
            if (value instanceof String) {
                return ((String) value).charAt(0);
            }
            throw new Exception("Could not convert value to java.lang.Character");
        }

        // Check if the type is already a Character
        if (value instanceof Character) {
            return value;
        }

        // Convert the value to String and then to Character
        return String.valueOf(value).charAt(0);
    }
}

