public static ThreadSnapshot parseFromLineWithTimeRange(String line, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {

    Pattern threadSnapshotPattern = Pattern.compile("thread-(?<threadId>\\d+),snap-(?<snapshotId>\\d+),state-(?<threadState>\\S+),file-(?<filepath>\\S+),snap-(?<timestamp>\\d+)");
    Matcher m = threadSnapshotPattern.matcher(line);
    if (!m.matches()) {
        return null;
    }

    int threadId = Integer.parseInt(m.group("threadId"));
    int snapshotId = Integer.parseInt(m.group("snapshotId"));
    String threadState = m.group("threadState");
    String filepath = m.group("filepath");
    long timestamp = Long.parseLong(m.group("timestamp"));

    ThreadSnapshot threadSnapshot = new ThreadSnapshot(threadId, snapshotId, threadState, filepath, timestamp);

    if (timestamp < timeRanges.get(0).startTime || timestamp >= timeRanges.get(timeRanges.size() - 1).endTime) {
        return null;
    }

    for (int i = 0; i < timeRanges.size() - 1; i++) {
        if (timestamp >= timeRanges.get(i).startTime && timestamp < timeRanges.get(i).endTime) {
            threadSnapshot.setTimeRange(timeRanges.get(i));
            break;
        }
    }

    return threadSnapshot;
}
